<script setup lang="ts">
import RecordSelect from './RecordSelect.vue'
import {reactive,ref,watch} from 'vue'
import type {FormInstance,FormRules} from 'element-plus'
import {saveEntity,useMutation} from '../composables/useResource'
export interface Field {key:string;label:string;kind?:'text'|'textarea'|'number'|'money'|'date'|'select'|'password';required?:boolean;options?:{label:string;value:any}[];min?:number;max?:number;span?:number;hint?:string}
const props=defineProps<{modelValue:boolean;title:string;endpoint:string;fields:Field[];record?:Record<string,any>;defaults?:Record<string,any>}>()
const emit=defineEmits<{'update:modelValue':[boolean];saved:[]}>()
const form=reactive<Record<string,any>>({}), formRef=ref<FormInstance>()
const {saving,run}=useMutation()
watch(()=>props.modelValue,open=>{if(open){Object.keys(form).forEach(key=>delete form[key]);for(const f of props.fields){const value=props.record?.[f.key]??props.defaults?.[f.key]??(f.kind==='number'?0:'');form[f.key]=f.kind==='number'?Number(value):value;}formRef.value?.clearValidate()}})
const rules=():FormRules=>Object.fromEntries(props.fields.filter(f=>f.required&&!(f.kind==='password'&&props.record?.id)).map(f=>[f.key,[{required:true,message:`请填写${f.label}`,trigger:'change'},...(f.kind==='money'?[{validator:(_:any,value:any,cb:any)=>Number.isFinite(Number(value))&&Number(value)>=0&&String(value).trim()!==''?cb():cb(new Error('请输入有效的非负金额')),trigger:'blur'}]:[])]]))
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;const payload={...form};for(const field of props.fields){if(field.kind==='date'&&!field.required&&!payload[field.key])payload[field.key]=null;}if(props.record?.id&&!payload.password)delete payload.password;if(await run(()=>saveEntity(props.endpoint,props.record?.id,payload),'保存成功')){emit('update:modelValue',false);emit('saved')}}
</script>
<template><el-dialog :model-value="modelValue" :title="title" width="760px" destroy-on-close :close-on-click-modal="false" @update:model-value="emit('update:modelValue',$event)"><el-form ref="formRef" :model="form" :rules="rules()" label-position="top" @submit.prevent="save"><div class="form-grid"><el-form-item v-for="field in fields" :key="field.key" :label="field.label" :prop="field.key" :class="{'full-width':field.span===2}"><RecordSelect v-if="field.kind==='select'&&['project_id','supplier_id','warehouse_id'].includes(field.key)" v-model="form[field.key]" :entity="({project_id:'projects',supplier_id:'suppliers',warehouse_id:'warehouses'} as Record<string,string>)[field.key]!"/><el-select v-else-if="field.kind==='select'" v-model="form[field.key]" filterable clearable :placeholder="`请选择${field.label}`"><el-option v-for="option in field.options" :key="String(option.value)" :label="option.label" :value="option.value"/></el-select><el-date-picker v-else-if="field.kind==='date'" v-model="form[field.key]" type="date" value-format="YYYY-MM-DD" style="width:100%"/><el-input-number v-else-if="field.kind==='number'" v-model="form[field.key]" :min="field.min??0" :max="field.max" :precision="field.key==='sort_order'?0:field.key==='rating'?1:3" controls-position="right" style="width:100%"/><el-input v-else v-model="form[field.key]" :type="field.kind==='textarea'?'textarea':field.kind==='password'?'password':'text'" :rows="3" :show-password="field.kind==='password'" :inputmode="field.kind==='money'?'decimal':undefined" :placeholder="field.kind==='money'?'0.00':field.kind==='password'&&record?.id?'留空保留原密码':`请输入${field.label}`"/><span v-if="field.hint" class="field-hint">{{field.hint}}</span></el-form-item></div></el-form><template #footer><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
